cat > src/main.rs <<'RUST'
use std::env;
use std::io::{self, Write};
use std::process::ExitCode;

mod args;
mod info;
mod help;
mod errors;

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let prog = prog_name(&argv[0]);
    match run(&prog, &argv[1..]) {
        Ok(code) => ExitCode::from(code),
        Err(e) => {
            let _ = writeln!(io::stderr(), "error: {}", e);
            ExitCode::from(1)
        }
    }
}

fn prog_name(argv0: &str) -> String {
    std::path::Path::new(argv0)
        .file_name()
        .and_then(|o| o.to_str())
        .unwrap_or(argv0)
        .to_string()
}

fn run(prog: &str, args: &[String]) -> Result<u8, String> {
    // No-args: show welcome message (only if stdin is clean etc)
    if args.is_empty() {
        print_welcome();
        return Ok(0);
    }

    // Parse top-level options / dispatch to subcommand
    args::dispatch(prog, args)
}

fn print_welcome() {
    print!("{}", WELCOME);
}

