cat > src/errors.rs <<'RUST'
use std::io::{self, Write};

/// Print an error in clap-like format to stderr and return the exit code.
pub fn unknown_subcommand(prog: &str, sub: &str) -> u8 {
    let _ = writeln!(io::stderr(),
        "error: unrecognized subcommand '{}'\n\nUsage: {} [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.",
        sub, prog);
    2
}

pub fn unexpected_arg(prog: &str, arg: &str, usage: &str) -> u8 {
    let _ = writeln!(io::stderr(),
        "error: unexpected argument '{}' found\n\nUsage: {}\n\nFor more information, try '--help'.",
        arg, usage.replace("executable", prog));
    2
}

pub fn missing_required(prog: &str, missing: &[&str], usage: &str) -> u8 {
    let mut out = String::new();
    out.push_str("error: the following required arguments were not provided:\n");
    for m in missing {
        out.push_str("  ");
        out.push_str(m);
        out.push('\n');
    }
    out.push_str("\nUsage: ");
    out.push_str(&usage.replace("executable", prog));
    out.push_str("\n\nFor more information, try '--help'.");
    let _ = writeln!(io::stderr(), "{}", out);
    2
}

pub fn invalid_value(name: &str, value: &str, possible: &[&str], tip: Option<&str>) -> u8 {
    let mut out = String::new();
    out.push_str(&format!(
        "error: invalid value '{}' for '{}'\n  [possible values: {}]\n",
        value, name, possible.join(", ")
    ));
    if let Some(t) = tip {
        out.push_str(&format!("\n  tip: a similar value exists: '{}'\n", t));
    }
    out.push_str("\nFor more information, try '--help'.");
    let _ = writeln!(io::stderr(), "{}", out);
    2
}

pub fn value_required(name: &str, possible: Option<&[&str]>) -> u8 {
    let mut out = format!(
        "error: a value is required for '{}' but none was supplied\n", name
    );
    if let Some(p) = possible {
        out.push_str(&format!("  [possible values: {}]\n", p.join(", ")));
    }
    out.push_str("\nFor more information, try '--help'.");
    let _ = writeln!(io::stderr(), "{}", out);
    2
}
