            out.push_str(&format!("  - {}\n", yaml_scalar(p)));
        }
    }
    out.push_str(&format!("  system: {}\n", sys_on));
    out.push_str(&format!("  embedded: {}\n", emb_on));
    out.push_str("packages:\n");
    out.push_str(&format!("  package-path: {}\n", yaml_scalar(&pkg)));
    out.push_str(&format!("  package-cache-path: {}\n", yaml_scalar(&cache)));
    out.push_str("env:\n");
    for k in ENV_KEYS {
        let v = env::var(k).ok();
        let val = match v {
            Some(s) => yaml_scalar(&s),
            None => "null".to_string(),
        };
        out.push_str(&format!("  {}: {}\n", k, val));
    }
    out
}

fn escape_json(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\x08' => out.push_str("\\b"),
            '\x0c' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out
}

fn yaml_scalar(s: &str) -> String {
    // Simple heuristic: if no special chars, emit bare; else single-quoted.
    // Also treat certain strings specially.
    if s.is_empty() {
        return "''".to_string();
    }
    let special = s.chars().any(|c| matches!(c, ':' | '#' | '{' | '}' | '[' | ']' | '&' | '*' | '!' | '|' | '>' | '\'' | '"' | '%' | '@' | '`' | ',' | '\n'))
        || s.starts_with(|c: char| c.is_whitespace())
        || s.ends_with(|c: char| c.is_whitespace());
    let reserved = matches!(
        s,
        "null" | "Null" | "NULL" | "~" | "true" | "True" | "TRUE"
            | "false" | "False" | "FALSE" | "yes" | "Yes" | "YES"
            | "no" | "No" | "NO" | "on" | "On" | "ON" | "off" | "Off" | "OFF"
    );
    let looks_numeric = s.parse::<f64>().is_ok();
    if special || reserved || looks_numeric {
        format!("'{}'", s.replace('\'', "''"))
    } else {
        s.to_string()
    }
}
