        for p in &paths {
            out.push_str(&format!("    - {}\n", p));
        }
    }
    out.push_str(&format!("  System fonts   {}\n", if sys_on { "on" } else { "off" }));
    out.push_str(&format!("  Embedded fonts {}\n\n", if emb_on { "on" } else { "off" }));
    out.push_str("Packages\n");
    out.push_str(&format!("  Package path       {}\n", pkg));
    out.push_str(&format!("  Package cache path {}\n\n", cache));
    out.push_str("Environment variables\n");
    // Width = 27 (longest key is TYPST_IGNORE_EMBEDDED_FONTS = 27 chars). Pad to 27.
    let width = ENV_KEYS.iter().map(|k| k.len()).max().unwrap_or(0);
    for k in ENV_KEYS {
        let v = env::var(k).ok();
        let vs = match &v {
            Some(s) => s.as_str(),
            None => "<unset>",
        };
        out.push_str(&format!("  {:width$} {}\n", k, vs, width = width));
    }
    out
}

