        out.push_str("\"build\":{");
        out.push_str(&format!("\"commit\":\"{}\",", COMMIT_FULL));
        out.push_str(&format!(
            "\"platform\":{{\"os\":\"{}\",\"arch\":\"{}\"}},",
            std::env::consts::OS, std::env::consts::ARCH
        ));
        out.push_str("\"settings\":{\"self-update\":false,\"http-server\":true}");
        out.push_str("},");
        out.push_str(&format!(
            "\"features\":{{\"html\":{},\"a11y-extras\":{}}},",
            html, a11y
        ));
        out.push_str("\"fonts\":{");
        out.push_str("\"paths\":[");
        for (i, p) in paths.iter().enumerate() {
            if i > 0 { out.push(','); }
            out.push_str(&format!("\"{}\"", escape_json(p)));
        }
        out.push_str(&format!("],\"system\":{},\"embedded\":{}}},", sys_on, emb_on));
        out.push_str("\"packages\":{");
        out.push_str(&format!("\"package-path\":\"{}\",", escape_json(&pkg)));
        out.push_str(&format!("\"package-cache-path\":\"{}\"", escape_json(&cache)));
        out.push_str("},");
        out.push_str("\"env\":{");
        for (i, k) in ENV_KEYS.iter().enumerate() {
            if i > 0 { out.push(','); }
            let v = env::var(k).ok();
            let val = match v {
                Some(s) => format!("\"{}\"", escape_json(&s)),
                None => "null".to_string(),
            };
            out.push_str(&format!("\"{}\":{}", k, val));
        }
        out.push('}');
        out.push('}');
        out
    }
}

