use std::io::{self, Write};
use crate::{help, info, errors};

// Top-level dispatch function
pub fn dispatch(prog: &str, args: &[String]) -> Result<u8, String> {
    // Parse top-level options until we hit a subcommand.
    let mut i = 0usize;
    let mut color: Option<String> = None;
    let mut cert: Option<String> = None;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--help" | "-h" => {
                print!("{}", help::render(help::MAIN, prog));
                return Ok(0);
            }
            "-V" | "--version" => {
                println!("typst {} ({})", info::VERSION, info::COMMIT_SHORT);
                return Ok(0);
            }
            "--color" => {
                i += 1;
                if i >= args.len() {
                    return Ok(errors::value_required("--color <COLOR>",
                        Some(&["auto","always","never"])));
                }
                let v = &args[i];
                if !matches!(v.as_str(), "auto"|"always"|"never") {
                    return Ok(errors::invalid_value("--color <COLOR>", v,
                        &["auto","always","never"], None));
                }
                color = Some(v.clone());
                i += 1;
            }
            s if s.starts_with("--color=") => {
                let v = &s["--color=".len()..];
                if !matches!(v, "auto"|"always"|"never") {
                    return Ok(errors::invalid_value("--color <COLOR>", v,
                        &["auto","always","never"], None));
                }
                color = Some(v.to_string());
                i += 1;
            }
            "--cert" => {
                i += 1;
                if i >= args.len() {
                    return Ok(errors::value_required("--cert <CERT>", None));
                }
                cert = Some(args[i].clone());
                i += 1;
            }
            s if s.starts_with("--cert=") => {
                cert = Some(s["--cert=".len()..].to_string());
                i += 1;
            }
            s if s.starts_with("-") => {
                let usage = "executable [OPTIONS] <COMMAND>";
                return Ok(errors::unexpected_arg(prog, s, usage));
            }
            _ => break,
        }
    }
    let _ = (color, cert);

    if i >= args.len() {
        // No subcommand given: same as --help, but in this case we should show welcome.
        // Actually from testing, `./executable` alone shows the welcome.
        // But `./executable --color auto` on its own with no subcommand?
        // Let's match clap: error about missing subcommand would be normal, but
        // Typst prints welcome when no args. Let's be conservative.
        crate::print_welcome();
        return Ok(0);
    }

    let sub = &args[i];
    let rest = &args[i+1..];
    match sub.as_str() {
        "compile" | "c" => run_compile(prog, rest, false),
        "watch" | "w" => run_compile(prog, rest, true),
        "init" => run_init(prog, rest),
        "query" => run_query(prog, rest),
        "eval" => run_eval(prog, rest),
        "fonts" => run_fonts(prog, rest),
        "update" => run_update(prog, rest),
        "completions" => run_completions(prog, rest),
        "info" => run_info(prog, rest),
        "help" => run_help(prog, rest),
        other => Ok(errors::unknown_subcommand(prog, other)),
    }
}

// Generic flag-eater that handles -h/--help for a subcommand.
fn maybe_help(args: &[String], long_text: &str, short_text: &str, prog: &str) -> Option<u8> {
    for a in args {
        match a.as_str() {
            "--help" => { print!("{}", help::render(long_text, prog)); return Some(0); }
            "-h" => { print!("{}", help::render(short_text, prog)); return Some(0); }
            _ => {}
        }
    }
    None
}

fn run_compile(prog: &str, args: &[String], watch: bool) -> Result<u8, String> {
    let (long, short, name) = if watch {
        (help::WATCH, help::WATCH_SHORT, "watch")
    } else {
        (help::COMPILE, help::COMPILE_SHORT, "compile")
    };
    if let Some(code) = maybe_help(args, long, short, prog) {
        return Ok(code);
    }
    // Simple scan: if no positional found, say INPUT missing.
    let mut positionals: Vec<&String> = Vec::new();
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        if a.starts_with("-") {
            // skip flags which take a value
            match a.as_str() {
                "--format" | "-f" | "--root" | "--input" | "--font-path"
                | "--package-path" | "--package-cache-path"
                | "--creation-timestamp" | "--pages" | "--pdf-standard"
                | "--ppi" | "--deps" | "--deps-format" | "-j" | "--jobs"
                | "--features" | "--diagnostic-format" | "--port" => {
                    let _ = iter.next();
                }
                _ => {}
            }
        } else {
            positionals.push(a);
        }
    }

    if positionals.is_empty() {
        let usage = format!("executable {} <INPUT> [OUTPUT]", name);
        return Ok(errors::missing_required(prog, &["<INPUT>"], &usage));
    }

    // We don't implement actual compilation. Emit an error.
    let input = positionals[0];
    let _ = writeln!(io::stderr(),
        "error: input file not found (searched at {})", input);
    Ok(1)
}

fn run_init(prog: &str, args: &[String]) -> Result<u8, String> {
    if let Some(code) = maybe_help(args, help::INIT, help::INIT_SHORT, prog) {
        return Ok(code);
    }
    // Determine first positional
    let mut positionals: Vec<&String> = Vec::new();
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        if a.starts_with("-") {
            match a.as_str() {
                "--package-path" | "--package-cache-path" => { let _ = iter.next(); }
                _ => {}
            }
        } else {
            positionals.push(a);
        }
    }
    if positionals.is_empty() {
        let usage = "executable init [OPTIONS] <TEMPLATE> [DIR]";
        return Ok(errors::missing_required(prog, &["<TEMPLATE>"], usage));
    }
    let t = positionals[0];
    if !t.starts_with('@') {
        let _ = writeln!(io::stderr(),
            "error: package specification must start with '@'");
        return Ok(1);
    }
    // We don't implement template fetching — respond with a generic network error.
    let _ = writeln!(io::stderr(),
        "error: failed to download package (network unavailable)");
    Ok(1)
}

fn run_query(prog: &str, args: &[String]) -> Result<u8, String> {
    if let Some(code) = maybe_help(args, help::QUERY, help::QUERY_SHORT, prog) {
        return Ok(code);
    }
    let mut positionals: Vec<&String> = Vec::new();
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        if a.starts_with("-") {
            match a.as_str() {
                "--field" | "--format" | "--target" | "--root" | "--input"
                | "--font-path" | "--package-path" | "--package-cache-path"
                | "--creation-timestamp" | "-j" | "--jobs"
                | "--features" | "--diagnostic-format" => { let _ = iter.next(); }
                _ => {}
            }
        } else {
            positionals.push(a);
        }
    }
    let usage = "executable query [OPTIONS] <INPUT> <SELECTOR>";
    if positionals.len() < 2 {
        let mut missing: Vec<&str> = Vec::new();
        if positionals.len() < 1 { missing.push("<INPUT>"); }
        missing.push("<SELECTOR>");
        return Ok(errors::missing_required(prog, &missing, usage));
    }
    let input = positionals[0];
    let _ = writeln!(io::stderr(),
        "error: input file not found (searched at {})", input);
    Ok(1)
}

fn run_eval(prog: &str, args: &[String]) -> Result<u8, String> {
    if let Some(code) = maybe_help(args, help::EVAL, help::EVAL_SHORT, prog) {
        return Ok(code);
    }
    let mut positionals: Vec<&String> = Vec::new();
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        if a.starts_with("-") {
            match a.as_str() {
                "--in" | "--target" | "--format" | "--root" | "--input"
                | "--font-path" | "--package-path" | "--package-cache-path"
                | "--creation-timestamp" | "-j" | "--jobs"
                | "--features" | "--diagnostic-format" => { let _ = iter.next(); }
                _ => {}
            }
        } else {
            positionals.push(a);
        }
    }
    let usage = "executable eval [OPTIONS] <EXPRESSION>";
    if positionals.is_empty() {
        return Ok(errors::missing_required(prog, &["<EXPRESSION>"], usage));
    }
    // Can't actually evaluate Typst. Emit an error.
    let _ = writeln!(io::stderr(),
        "error: evaluation of Typst expressions is not supported in this build");
    Ok(1)
}

fn run_fonts(prog: &str, args: &[String]) -> Result<u8, String> {
    if let Some(code) = maybe_help(args, help::FONTS, help::FONTS_SHORT, prog) {
        return Ok(code);
    }
    let mut variants = false;
    let mut ignore_system = info::env_is_set_true("TYPST_IGNORE_SYSTEM_FONTS");
    let mut ignore_embedded = info::env_is_set_true("TYPST_IGNORE_EMBEDDED_FONTS");
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        match a.as_str() {
            "--variants" => variants = true,
            "--ignore-system-fonts" => ignore_system = true,
            "--ignore-embedded-fonts" => ignore_embedded = true,
            "--font-path" => { let _ = iter.next(); }
            s if s.starts_with("--font-path=") => {}
            other => {
                let usage = "executable fonts [OPTIONS]";
                return Ok(errors::unexpected_arg(prog, other, usage));
            }
        }
    }
    // Output the embedded font list (only).
    if !ignore_embedded {
        for family in EMBEDDED_FAMILIES {
            println!("{}", family.name);
            if variants {
                for v in family.variants {
                    println!(
                        "- Style: {}, Weight: {}, Stretch: FontStretch({}), Path: <embedded>",
                        v.style, v.weight, v.stretch
                    );
                }
            }
        }
    }
    let _ = (ignore_system,);
    Ok(0)
}

fn run_update(prog: &str, args: &[String]) -> Result<u8, String> {
    if let Some(code) = maybe_help(args, help::UPDATE, help::UPDATE_SHORT, prog) {
        return Ok(code);
    }
    let _ = writeln!(io::stderr(),
        "error: self-updating is not enabled for this executable, please update with the package manager or mechanism used for initial installation");
    Ok(1)
}

fn run_completions(prog: &str, args: &[String]) -> Result<u8, String> {
    // Help has no long/short distinction here (both same).
    for a in args {
        if a == "--help" || a == "-h" {
            print!("{}", help::render(help::COMPLETIONS, prog));
            return Ok(0);
        }
    }
    let mut positional: Option<&String> = None;
    for a in args {
        if a.starts_with("-") {
            let usage = "executable completions <SHELL>";
            return Ok(errors::unexpected_arg(prog, a, usage));
        }
        if positional.is_some() {
            let usage = "executable completions <SHELL>";
            return Ok(errors::unexpected_arg(prog, a, usage));
        }
        positional = Some(a);
    }
    let shell = match positional {
        Some(s) => s.as_str(),
        None => {
            // missing required
            let usage = "executable completions <SHELL>";
            return Ok(errors::missing_required(prog, &["<SHELL>"], usage));
        }
    };
    let script = match shell {
        "bash" => help::COMP_BASH,
        "zsh" => help::COMP_ZSH,
        "fish" => help::COMP_FISH,
        "elvish" => help::COMP_ELVISH,
        "powershell" => help::COMP_PS,
        other => {
            return Ok(errors::invalid_value("<SHELL>", other,
                &["bash","elvish","fish","powershell","zsh"], None));
        }
    };
    print!("{}", script);
    Ok(0)
}

fn run_info(prog: &str, args: &[String]) -> Result<u8, String> {
    if let Some(code) = maybe_help(args, help::INFO, help::INFO_SHORT, prog) {
        return Ok(code);
    }
    let mut format: Option<String> = None;
    let mut pretty = false;
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        match a.as_str() {
            "-f" | "--format" => {
                let next = iter.next();
                match next {
                    None => {
                        return Ok(errors::value_required(
                            "--format <FORMAT>",
                            Some(&["json","yaml"]),
                        ));
                    }
                    Some(v) => {
                        if !matches!(v.as_str(), "json"|"yaml") {
                            return Ok(errors::invalid_value(
                                "--format <FORMAT>", v,
                                &["json","yaml"], None,
                            ));
                        }
                        format = Some(v.clone());
                    }
                }
            }
            s if s.starts_with("--format=") => {
                let v = &s["--format=".len()..];
                if !matches!(v, "json"|"yaml") {
                    return Ok(errors::invalid_value(
                        "--format <FORMAT>", v,
                        &["json","yaml"], None,
                    ));
                }
                format = Some(v.to_string());
            }
            "--pretty" => { pretty = true; }
            other => {
                let usage = "executable info [OPTIONS]";
                return Ok(errors::unexpected_arg(prog, other, usage));
            }
        }
    }
    match format.as_deref() {
