                cert = Some(args[i].clone());
                i += 1;
            }
            s if s.starts_with("--cert=") => {
                cert = Some(s["--cert=".len()..].to_string());
                i += 1;
            }
            s if s.starts_with("-") => {
                let usage = "executable [OPTIONS] <COMMAND>";
                return Ok(errors::unexpected_arg(prog, s, usage));
            }
            _ => break,
        }
    }
    let _ = (color, cert);

    if i >= args.len() {
        // No subcommand given: same as --help, but in this case we should show welcome.
