// Generic flag-eater that handles -h/--help for a subcommand.
fn maybe_help(args: &[String], long_text: &str, short_text: &str, prog: &str) -> Option<u8> {
    for a in args {
        match a.as_str() {
            "--help" => { print!("{}", help::render(long_text, prog)); return Some(0); }
            "-h" => { print!("{}", help::render(short_text, prog)); return Some(0); }
            _ => {}
        }
    }
    None
}

fn run_compile(prog: &str, args: &[String], watch: bool) -> Result<u8, String> {
    let (long, short, name) = if watch {
        (help::WATCH, help::WATCH_SHORT, "watch")
    } else {
        (help::COMPILE, help::COMPILE_SHORT, "compile")
    };
    if let Some(code) = maybe_help(args, long, short, prog) {
        return Ok(code);
    }
    // Simple scan: if no positional found, say INPUT missing.
    let mut positionals: Vec<&String> = Vec::new();
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        if a.starts_with("-") {
            // skip flags which take a value
            match a.as_str() {
                "--format" | "-f" | "--root" | "--input" | "--font-path"
                | "--package-path" | "--package-cache-path"
                | "--creation-timestamp" | "--pages" | "--pdf-standard"
                | "--ppi" | "--deps" | "--deps-format" | "-j" | "--jobs"
                | "--features" | "--diagnostic-format" | "--port" => {
                    let _ = iter.next();
                }
                _ => {}
            }
        } else {
            positionals.push(a);
        }
    }

    if positionals.is_empty() {
        let usage = format!("executable {} <INPUT> [OUTPUT]", name);
        return Ok(errors::missing_required(prog, &["<INPUT>"], &usage));
    }

    // We don't implement actual compilation. Emit an error.
    let input = positionals[0];
    let _ = writeln!(io::stderr(),
        "error: input file not found (searched at {})", input);
    Ok(1)
}

fn run_init(prog: &str, args: &[String]) -> Result<u8, String> {
    if let Some(code) = maybe_help(args, help::INIT, help::INIT_SHORT, prog) {
        return Ok(code);
    }
    // Determine first positional
    let mut positionals: Vec<&String> = Vec::new();
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        if a.starts_with("-") {
            match a.as_str() {
                "--package-path" | "--package-cache-path" => { let _ = iter.next(); }
                _ => {}
            }
        } else {
            positionals.push(a);
        }
    }
    if positionals.is_empty() {
        let usage = "executable init [OPTIONS] <TEMPLATE> [DIR]";
        return Ok(errors::missing_required(prog, &["<TEMPLATE>"], usage));
    }
    let t = positionals[0];
    if !t.starts_with('@') {
        let _ = writeln!(io::stderr(),
            "error: package specification must start with '@'");
        return Ok(1);
    }
    // We don't implement template fetching — respond with a generic network error.
    let _ = writeln!(io::stderr(),
        "error: failed to download package (network unavailable)");
    Ok(1)
}

fn run_query(prog: &str, args: &[String]) -> Result<u8, String> {
    if let Some(code) = maybe_help(args, help::QUERY, help::QUERY_SHORT, prog) {
        return Ok(code);
    }
    let mut positionals: Vec<&String> = Vec::new();
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        if a.starts_with("-") {
            match a.as_str() {
                "--field" | "--format" | "--target" | "--root" | "--input"
                | "--font-path" | "--package-path" | "--package-cache-path"
                | "--creation-timestamp" | "-j" | "--jobs"
                | "--features" | "--diagnostic-format" => { let _ = iter.next(); }
                _ => {}
            }
        } else {
            positionals.push(a);
        }
    }
    let usage = "executable query [OPTIONS] <INPUT> <SELECTOR>";
    if positionals.len() < 2 {
        let mut missing: Vec<&str> = Vec::new();
        if positionals.len() < 1 { missing.push("<INPUT>"); }
        missing.push("<SELECTOR>");
        return Ok(errors::missing_required(prog, &missing, usage));
    }
    let input = positionals[0];
    let _ = writeln!(io::stderr(),
        "error: input file not found (searched at {})", input);
    Ok(1)
}

fn run_eval(prog: &str, args: &[String]) -> Result<u8, String> {
