fn run_completions(prog: &str, args: &[String]) -> Result<u8, String> {
    // Help has no long/short distinction here (both same).
    for a in args {
        if a == "--help" || a == "-h" {
            print!("{}", help::render(help::COMPLETIONS, prog));
            return Ok(0);
        }
    }
    let mut positional: Option<&String> = None;
    for a in args {
        if a.starts_with("-") {
            let usage = "executable completions <SHELL>";
            return Ok(errors::unexpected_arg(prog, a, usage));
        }
        if positional.is_some() {
            let usage = "executable completions <SHELL>";
            return Ok(errors::unexpected_arg(prog, a, usage));
        }
        positional = Some(a);
    }
    let shell = match positional {
        Some(s) => s.as_str(),
        None => {
            // missing required
            let usage = "executable completions <SHELL>";
            return Ok(errors::missing_required(prog, &["<SHELL>"], usage));
        }
    };
    let script = match shell {
        "bash" => help::COMP_BASH,
        "zsh" => help::COMP_ZSH,
        "fish" => help::COMP_FISH,
        "elvish" => help::COMP_ELVISH,
        "powershell" => help::COMP_PS,
        other => {
            return Ok(errors::invalid_value("<SHELL>", other,
                &["bash","elvish","fish","powershell","zsh"], None));
        }
    };
    print!("{}", script);
    Ok(0)
}

