fn run_info(prog: &str, args: &[String]) -> Result<u8, String> {
    if let Some(code) = maybe_help(args, help::INFO, help::INFO_SHORT, prog) {
        return Ok(code);
    }
    let mut format: Option<String> = None;
    let mut pretty = false;
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        match a.as_str() {
            "-f" | "--format" => {
                let next = iter.next();
                match next {
                    None => {
                        return Ok(errors::value_required(
                            "--format <FORMAT>",
                            Some(&["json","yaml"]),
                        ));
                    }
                    Some(v) => {
                        if !matches!(v.as_str(), "json"|"yaml") {
                            return Ok(errors::invalid_value(
                                "--format <FORMAT>", v,
                                &["json","yaml"], None,
                            ));
                        }
                        format = Some(v.clone());
                    }
                }
            }
            s if s.starts_with("--format=") => {
                let v = &s["--format=".len()..];
                if !matches!(v, "json"|"yaml") {
                    return Ok(errors::invalid_value(
                        "--format <FORMAT>", v,
                        &["json","yaml"], None,
                    ));
                }
                format = Some(v.to_string());
            }
            "--pretty" => { pretty = true; }
            other => {
                let usage = "executable info [OPTIONS]";
                return Ok(errors::unexpected_arg(prog, other, usage));
            }
        }
    }
    match format.as_deref() {
        None => print!("{}", info::human()),
        Some("json") => {
            let s = info::json(pretty);
            if pretty { print!("{}", s); } else { println!("{}", s); }
        }
        Some("yaml") => {
            print!("{}", info::yaml());
        }
        _ => unreachable!(),
    }
    Ok(0)
}

fn run_help(prog: &str, args: &[String]) -> Result<u8, String> {
    // `help` followed by a subcommand prints the LONG help for that subcommand.
    if args.is_empty() {
        print!("{}", help::render(help::MAIN, prog));
        return Ok(0);
    }
    // Navigate into nested subcommands.
    let text = match args[0].as_str() {
        "compile" | "c" => help::COMPILE,
        "watch" | "w" => help::WATCH,
        "init" => help::INIT,
        "query" => help::QUERY,
        "eval" => help::EVAL,
        "fonts" => help::FONTS,
        "update" => help::UPDATE,
        "completions" => help::COMPLETIONS,
        "info" => help::INFO,
        "help" => help::HELP,
        other => {
            let _ = writeln!(io::stderr(),
                "error: unrecognized subcommand '{}'\n\nUsage: {} help [COMMAND]...\n\nFor more information, try '--help'.",
                other, prog);
            return Ok(2);
        }
    };
    print!("{}", help::render(text, prog));
    Ok(0)
}

