            if let Some(v) = inline { return Ok(v.to_string()); }
            match iter.next() {
                Some(v) => Ok(v.clone()),
                None => Err(errors::value_required(flag_name, None)),
            }
        };
        match key {
            "-f" | "--format" => {
                let v = match take_val(&mut iter, val_inline, "--format <FORMAT>") {
                    Ok(v) => v, Err(c) => return Ok(c),
                };
                if let Err(c) = validate_value("--format <FORMAT>", &v, FORMATS) {
                    return Ok(c);
                }
            }
            "--pdf-standard" => {
                let v = match take_val(&mut iter, val_inline, "--pdf-standard <PDF_STANDARD>") {
                    Ok(v) => v, Err(c) => return Ok(c),
                };
                for part in v.split(',') {
                    if let Err(c) = validate_value("--pdf-standard <PDF_STANDARD>", part, PDF_STANDARDS) {
                        return Ok(c);
                    }
                }
            }
            "--deps-format" => {
                let v = match take_val(&mut iter, val_inline, "--deps-format <DEPS_FORMAT>") {
                    Ok(v) => v, Err(c) => return Ok(c),
                };
                if let Err(c) = validate_value("--deps-format <DEPS_FORMAT>", &v, DEPS_FORMATS) {
                    return Ok(c);
                }
            }
            "--diagnostic-format" => {
                let v = match take_val(&mut iter, val_inline, "--diagnostic-format <DIAGNOSTIC_FORMAT>") {
                    Ok(v) => v, Err(c) => return Ok(c),
                };
                if let Err(c) = validate_value("--diagnostic-format <DIAGNOSTIC_FORMAT>", &v, DIAG_FORMATS) {
                    return Ok(c);
                }
            }
            "--features" => {
                let v = match take_val(&mut iter, val_inline, "--features <FEATURES>") {
                    Ok(v) => v, Err(c) => return Ok(c),
                };
                for part in v.split(',') {
                    if part.is_empty() { continue; }
                    if let Err(c) = validate_value("--features <FEATURES>", part, FEATURES_SET) {
                        return Ok(c);
                    }
                }
            }
            "--root" | "--input" | "--font-path" | "--package-path"
            | "--package-cache-path" | "--creation-timestamp" | "--pages"
            | "--ppi" | "--deps" | "-j" | "--jobs" | "--port" => {
                let _ = take_val(&mut iter, val_inline, key);
            }
            "--ignore-system-fonts" | "--ignore-embedded-fonts"
            | "--no-pdf-tags" | "--no-serve" | "--no-reload" => {}
            "--open" | "--timings" => {
                // Optional value: consume next only if it doesn't start with '-'.
                if val_inline.is_some() {
                    // ok, consumed
                } else if let Some(next) = iter.peek() {
                    if !next.starts_with("-") {
                        iter.next();
                    }
                }
            }
            other if other.starts_with("-") => {
                let usage = format!("executable {} [OPTIONS] <INPUT> [OUTPUT]", name);
                return Ok(errors::unexpected_arg(prog, other, &usage));
            }
            _ => { positionals.push(a); }
        }
    }

    if positionals.is_empty() {
        let usage = format!("executable {} <INPUT> [OUTPUT]", name);
        return Ok(errors::missing_required(prog, &["<INPUT>"], &usage));
    }

    // We don't implement actual compilation. Emit an error.
    let input = positionals[0];
    let _ = writeln!(io::stderr(),
        "error: input file not found (searched at {})", input);
    Ok(1)
}
